const sources =
  'UEsDBBQAAAAIABm1eF18VaLoSgAAAEgAAAAKAAAAUkVBRE1FLnR4dATBwQ2AIBAEwL+JPWwFVOHbHggu4Yx4ZL2g5TuzsTuySrNJVBeiEXYHVXMhhjiNb8LuGPKTJVDt4oMsgt9wBY+0Lj8AAAD//wMAUEsBAhQAFAAAAAgAGbV4XXxVouhKAAAASAAAAAoAAAAAAAAAAAAAAAAAAAAAAFJFQURNRS50eHRQSwUGAAAAAAEAAQA4AAAAcgAAAAAA';
const withMaterials =
  '';

export function archiveFixture(includeMaterials: boolean) {
  return Uint8Array.from(atob(includeMaterials ? withMaterials : sources), (char) =>
    char.charCodeAt(0),
  );
}
